<script setup lang="ts">import type { Station } from '~/types/api'; defineProps<{ modelValue:string; stations:Station[]; loading?:boolean }>(); defineEmits<{ 'update:modelValue':[value:string] }>()</script>
<template><label><span class="label">Estación meteorológica</span><select class="select" :disabled="loading" :value="modelValue" @change="$emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option value="">Seleccione una estación</option><option v-for="station in stations" :key="station.id" :value="station.id">{{ station.name }}<template v-if="station.locality"> · {{ station.locality }}</template></option></select></label></template>
